// is `currentColor` (the renderer sets it: brown, or red for what only the keeper sees), washes are
// fixed pale colours. A stamp's top edge is its back (a bed's head, a bookcase against the wall):
// rotation turns it. Any stamp can be replaced by another drawing (QuiverAI…) with the same id and
// size, as long as it stays inside its box and passes sanitizeSvg.
import type { MapKind } from './model.ts'

export interface Stamp {
  id: string
  /** Which kinds of map offer it first (the editor's palette, the model's catalogue). */
  kinds: MapKind[]
  /** Width and height in cells, unrotated. */
  size: [number, number]
  label: { fr: string; en: string }
  /** SVG content in a box of 100·w × 100·h units. */
  body: string
}

