/** Ink lines. */
const ink = (w = 3) => `fill="none" stroke="currentColor" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"`
/** A see-through wash with a thinner ink outline. */
const tint = (c: string, opacity: number, w = 2) => `fill="${c}"${opacity < 1 ? ` fill-opacity="${opacity}"` : ''} stroke="currentColor" stroke-width="${w}" stroke-linejoin="round"`
/** A filled shape with an ink outline. */
const wash = (c: string, w = 3) => `fill="${c}" stroke="currentColor" stroke-width="${w}" stroke-linejoin="round"`

const rect = (x: number, y: number, w: number, h: number, style: string, rx = 0) =>
  `<rect x="${f(x)}" y="${f(y)}" width="${f(w)}" height="${f(h)}"${rx ? ` rx="${f(rx)}"` : ''} ${style}/>`
const circle = (cx: number, cy: number, r: number, style: string) => `<circle cx="${f(cx)}" cy="${f(cy)}" r="${f(r)}" ${style}/>`
const path = (d: string, style: string) => `<path d="${d}" ${style}/>`

/** Small deterministic noise from a number. */
const noise = (i: number) => {
  const s = Math.sin(i * 12.9898 + 78.233) * 43758.5453
  return s - Math.floor(s)
}

/** A lumpy round outline (tree canopies, bushes): `bumps` arcs bulging out of a circle. */
function blob(cx: number, cy: number, r: number, bumps: number, seed = 1, bulge = 1.22): string {
  const pts: [number, number][] = []
  for (let i = 0; i < bumps; i++) {
    const a = (i / bumps) * Math.PI * 2 + noise(seed + i) * 0.25
    const rr = r * (0.9 + noise(seed * 3 + i) * 0.12)
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr])
  }
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`
  for (let i = 0; i < bumps; i++) {
    const [x2, y2] = pts[(i + 1) % bumps]
    const a = ((i + 0.5) / bumps) * Math.PI * 2 + noise(seed + i) * 0.12
    d += `Q${f(cx + Math.cos(a) * r * bulge)} ${f(cy + Math.sin(a) * r * bulge)} ${f(x2)} ${f(y2)}`
  }
  return d + 'Z'
}

/** A spiky round outline (a conifer from above). */
function star(cx: number, cy: number, r: number, spikes: number, inner = 0.72): string {
  let d = ''
  for (let i = 0; i < spikes * 2; i++) {
    const a = (i / (spikes * 2)) * Math.PI * 2
    const rr = i % 2 ? r * inner : r * (0.92 + noise(i) * 0.1)
    d += `${i ? 'L' : 'M'}${f(cx + Math.cos(a) * rr)} ${f(cy + Math.sin(a) * rr)}`
  }
  return d + 'Z'
}

/** An irregular stone. */
function stone(cx: number, cy: number, r: number, seed: number, sides = 7): string {
  let d = ''
  for (let i = 0; i < sides; i++) {
    const a = (i / sides) * Math.PI * 2 + noise(seed + i) * 0.4
    const rr = r * (0.75 + noise(seed * 7 + i) * 0.35)
    d += `${i ? 'L' : 'M'}${f(cx + Math.cos(a) * rr)} ${f(cy + Math.sin(a) * rr)}`
  }
  return d + 'Z'
}

/** Parallel lines across a box, for planks, treads and tiles. */
function lines(x0: number, y0: number, x1: number, y1: number, step: number, horizontal: boolean): string {
  let d = ''
  if (horizontal) for (let y = y0 + step; y < y1 - 0.1; y += step) d += `M${f(x0)} ${f(y)}H${f(x1)}`
  else for (let x = x0 + step; x < x1 - 0.1; x += step) d += `M${f(x)} ${f(y0)}V${f(y1)}`
  return d
}

