const books = (() => {
  let d = ''
  let x = 12
  let i = 0
  while (x < 188) {
    d += `M${f(x)} ${f(12 + noise(i) * 4)}V38`
    x += 6 + Math.round(noise(i + 9) * 4)
    i++
  }
  return d
})()

