function roof(w: number, h: number, colour: string, hatch: number): string {
  // A gable roof from above: the ridge along the long side, tiles as short strokes.
  const along = w >= h
  const ridge = along ? `M14 ${f(h / 2)}H${f(w - 14)}` : `M${f(w / 2)} 14V${f(h - 14)}`
  let tiles = ''
  if (along) for (let x = 24; x < w - 20; x += hatch) tiles += `M${f(x)} 20V${f(h / 2 - 6)}M${f(x + hatch / 2)} ${f(h / 2 + 6)}V${f(h - 20)}`
  else for (let y = 24; y < h - 20; y += hatch) tiles += `M20 ${f(y)}H${f(w / 2 - 6)}M${f(w / 2 + 6)} ${f(y + hatch / 2)}H${f(w - 20)}`
  return rect(10, 10, w - 20, h - 20, wash(colour)) + path(tiles, `${ink(1)} opacity=".55"`) + path(ridge, ink(3))
}

