const radial = (cx: number, cy: number, r0: number, r1: number, n: number, turn = 0) =>
  Array.from({ length: n }, (_, i) => {
    const a = (i / n) * Math.PI * 2 + turn
    return `M${f(cx + Math.cos(a) * r0)} ${f(cy + Math.sin(a) * r0)}L${f(cx + Math.cos(a) * r1)} ${f(cy + Math.sin(a) * r1)}`
  }).join('')
const dot = (cx: number, cy: number, r = 2.5) => circle(cx, cy, r, 'fill="currentColor"')
